package com.kingbrezz.donutshop;
import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
public final class ShopEditCommand implements CommandExecutor,TabCompleter {private final DonutShop plugin;public ShopEditCommand(DonutShop p){plugin=p;}
 @Override public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){plugin.getLanguageManager().send(s,"messages.player-only");return true;}if(!p.hasPermission("donutshop.admin.shopedit")){plugin.getLanguageManager().send(p,"messages.no-permission");return true;}if(!plugin.getConfig().getBoolean("shop-edit.enabled",true)){plugin.getLanguageManager().send(p,"messages.shopedit-disabled");return true;}if(a.length!=1){plugin.getLanguageManager().send(p,"messages.shopedit-usage");return true;}ShopCategory cat=plugin.getShopManager().getCategory(a[0]);if(cat==null){plugin.getLanguageManager().send(p,"messages.category-not-found",Map.of("category",a[0]));return true;}ShopEditMenu.open(plugin,p,cat);return true;}
 @Override public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(a.length!=1)return List.of();String q=a[0].toLowerCase(Locale.ROOT);return plugin.getShopManager().getCategories().stream().map(ShopCategory::id).filter(x->x.startsWith(q)).toList();}}
